def generate_decomposition(n, current_sum=0, current_sequence=[]):
    """Generate a decomposition of n as a sum of squares."""
    if current_sum == n:
        return current_sequence if is_valid_decomposition(current_sequence) else None
    if current_sum > n:
        return None
    largest_square = find_largest_square(n - current_sum)
    if largest_square == 0:
        return None
    return generate_decomposition(n, current_sum + largest_square, current_sequence + [largest_square])

def decompose(n):
    """Decompose n into a strictly increasing sequence of squares."""
    return generate_decomposition(n)
