def pascal_triangle(n):
    """Generate the n-th row of Pascal's triangle."""
    if n == 0:
        return [1]
    row = [1]
    for i in range(1, n + 1):
        row.append(row[i - 1] * (n - i + 1) // i)
    return row

def bernoulli_number(n):
    """Calculate the n-th Bernoulli number."""
    if n == 0:
        return Fraction(1)
    if n == 1:
        return Fraction(-1, 2)

    pascal_row = pascal_triangle(n)
    bernoulli_sum = Fraction(0)
    for k in range(n + 1):
        bernoulli_sum += Fraction(pascal_row[k] * bernoulli_number(k), n + 1)

    return -bernoulli_sum
