def factorial(n):
    """Calculate the factorial of a given number n."""
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

def permutation_count(n, k):
    """Calculate the number of permutations of n items taken k at a time."""
    return factorial(n) // factorial(n - k)

def find_middle_index(n):
    """Find the middle index for a given length n."""
    return n // 2

def middle_permutation(string):
    """Return the middle permutation of the given string."""
    n = len(string)
    sorted_string = sorted(string)
    middle_index = find_middle_index(n)
    result = []

    for i in range(n):
        count = permutation_count(n - i - 1, n // 2)
        if middle_index < count:
            result.append(sorted_string.pop(0))
        else:
            middle_index -= count

    return ''.join(result)
